text:
{
 "title": "育児・介護休業法と雇用保険法の改正",
 "lead": {
  "es": "子《こ》どもが生《う》まれたときなどに仕事《しごと》をやめなくてすむよう、とくに男《おとこ》の人《ひと》が育児休業《いくじきゅうぎょう》をとりやすくするための法律《ほうりつ》です。",
  "hs": "出産・育児で仕事をやめる人をへらし、とくに男性の育児休業の取得を進めるため、育児・｜介護《かいご》休業法と｜雇用《こよう》保険法を改正した法律です。",
  "std": "出産・育児等による離職を防ぎ、特に男性の育児休業取得を促進し、男女とも仕事と育児等を両立できるようにするための法律です。",
  "univ": "出産・育児等による労働者の離職を防ぎ、特に男性の育児休業の取得の促進を図るとともに、希望に応じて男女ともに仕事と育児等を両立できるようにするため、育児・介護休業法及び雇用保険法の一部を改正する法律。"
 },
 "facts": [
  {
   "es": "子《こ》どもが生《う》まれてから8週間《しゅうかん》の間《あいだ》に、4週間《しゅうかん》まで休《やす》める「出生時育児休業《しゅっしょうじいくじきゅうぎょう》」をつくります。原則《げんそく》2週間前《しゅうかんまえ》までに会社《かいしゃ》に伝《つた》え、あわせて28日《にち》まで、2回《かい》に分《わ》けてとれます。本人《ほんにん》がよいと言《い》えば、決《き》まった範囲《はんい》で休《やす》みの間《あいだ》に働《はたら》くこともできます。",
   "hs": "子の出生から8週間の間に、4週間までの「出生時育児休業」をとれるようにする。原則として休む2週間前までに会社に申し出て、合計28日を限度に2回に分けられる。本人が働ける日を申し出て同意した場合に限り、決まった｜範囲《はんい》で休業中に働くこともできる。",
   "std": "労働者は、原則として休業の2週間前までに申し出ることで、子の出生日から8週間を経過する日の翌日までの期間内に、4週間以内の出生時育児休業を取得でき、合計28日を限度に2回に分割できます。事業主は、労働者から就業可能日等の申出があれば、その範囲内で日時を提示し、労働者の同意を得た場合に限り、省令で定める範囲内で就業させることができます。",
   "univ": "労働者は、原則として休業の2週間前までに事業主に申し出ることにより、子の出生の日から起算して8週間を経過する日の翌日までの期間内に4週間以内の期間を定めてする出生時育児休業をすることができ、合計28日を限度として2回に分割することができる。事業主は、出生時育児休業申出をした労働者から就業可能日等の申出があった場合には、その範囲内で日時を提示し、当該労働者の同意を得た場合に限り、厚生労働省令で定める範囲内で就業させることができる。"
  },
  {
   "es": "会社《かいしゃ》は、育児休業《いくじきゅうぎょう》についての研修《けんしゅう》や相談《そうだん》の窓口《まどぐち》づくりなど、どれかをしなければなりません。子《こ》どもができたと伝《つた》えた人《ひと》には、育児休業《いくじきゅうぎょう》のしくみを知《し》らせ、とるつもりかを聞《き》かなければなりません。",
   "hs": "会社は、育児休業についての研修、相談体制づくりなど、育児休業をとりやすくする｜措置《そち》のどれかをしなければならない。本人や｜配偶者《はいぐうしゃ》の｜妊娠《にんしん》・出産を申し出た人には、育児休業の制度などを知らせ、とるつもりかを面談などで確かめなければならない。",
   "std": "事業主は、育児休業に係る研修の実施、相談体制の整備等の雇用環境整備措置のいずれかを講じなければなりません。また、本人又は配偶者の妊娠・出産等を申し出た労働者に、育児休業制度等を周知し、取得の意向を面談等で確認しなければなりません。",
   "univ": "事業主は、育児休業に係る研修の実施、育児休業に関する相談体制の整備又はその他厚生労働省令で定める育児休業に係る雇用環境の整備に関する措置のいずれかを講じなければならない。事業主は、労働者が当該労働者又はその配偶者が妊娠し、又は出産したこと等を申し出たときは、育児休業に関する制度等を知らせるとともに、育児休業申出に係る意向を確認するための面談等の措置を講じなければならない。"
  },
  {
   "es": "1さいまでの子《こ》どもの育児休業《いくじきゅうぎょう》も、2回《かい》に分《わ》けてとれるようにします。",
   "hs": "1｜歳《さい》までの子の育児休業（出生時育児休業をのぞく）を、2回に分けて申し出られるようにする。",
   "std": "1歳に満たない子についての育児休業（出生時育児休業を除く）を、分割して2回申し出られるようにします。",
   "univ": "1歳に満たない子についてする育児休業（出生時育児休業を除く。）について、分割して2回の育児休業申出をすることができる。"
  },
  {
   "es": "働《はたら》く人《ひと》が1000人《にん》より多《おお》い会社《かいしゃ》は、毎年《まいとし》1回《かい》以上《いじょう》、育児休業《いくじきゅうぎょう》をとった様子《ようす》を公表《こうひょう》します。",
   "hs": "常に1000人をこえる人をやとう会社は、毎年少なくとも1回、育児休業の取得｜状況《じょうきょう》を公表しなければならない。",
   "std": "常時雇用する労働者が1000人を超える事業主は、毎年少なくとも1回、育児休業の取得状況を公表しなければなりません。",
   "univ": "常時雇用する労働者の数が1000人を超える事業主は、毎年少なくとも1回、その雇用する労働者の育児休業の取得の状況を公表しなければならない。"
  },
  {
   "es": "期間《きかん》を決《き》めて働《はたら》く人《ひと》が育児休業《いくじきゅうぎょう》や介護休業《かいごきゅうぎょう》をとるときの「1年《ねん》以上《いじょう》働《はたら》いている人《ひと》」という条件《じょうけん》をなくします。雇用保険《こようほけん》から出《で》るお金《かね》に「出生時育児休業給付金《しゅっしょうじいくじきゅうぎょうきゅうふきん》」を加《くわ》えます。",
   "hs": "期間を決めてやとわれる人の育児休業・｜介護《かいご》休業について、「同じ会社に1年以上続けてやとわれている人」という条件をなくす。育児休業給付に、出生時育児休業給付金を加える。",
   "std": "有期雇用労働者の育児休業・介護休業の申出について、「引き続き雇用された期間が1年以上である者」との要件を削除します。育児休業給付に出生時育児休業給付金を追加します。",
   "univ": "期間を定めて雇用される者の育児休業及び介護休業の申出について、「当該事業主に引き続き雇用された期間が1年以上である者」との要件を削る。育児休業給付に出生時育児休業給付金を追加する。"
  },
  {
   "es": "この法律《ほうりつ》は、一部《いちぶ》をのぞき、令和《れいわ》4年《ねん》4月《がつ》1日《ついたち》から使《つか》われます。",
   "hs": "この法律は、一部をのぞき、令和4年4月1日から｜施行《しこう》する。",
   "std": "一部を除き、令和4年4月1日から施行します。",
   "univ": "この法律は、一部の規定を除き、令和4年4月1日から施行する。"
  }
 ]
}
